import TiptapEditor from '@/shared/data/forms/form-editors/tiptapeditor'

const Select = dynamic(() => import('react-select'), { ssr: false })

type PlaylistItemType = 'video' | 'youtube' | 'quiz' | 'pdf' | 'blog' | 'test'

type QuizOption = {
  id: string
  text: string
  correct: boolean
}

type QuizQuestion = {
  id: string
  question: string
  options: QuizOption[]
  multipleCorrect: boolean
}

type PlaylistItem = {
  id: string
  type: PlaylistItemType
  title: string
  source: string
  duration?: string
  blogContent?: string
  videoPreview?: string
  quizData?: QuizQuestion[]
}

type ModuleFormData = {
  categoryId: string
  name: string
  coverImage: string
  shortDescription: string
  studentIds: string[]
  mentorIds: string[]
  playlist: PlaylistItem[]
}

